select
users.*
from users users

    and users.id = #{id}
    and users.name like concat('%',#{name},'%')
    and users.sex = #{sex}
    and users.age = #{age}
    and users.username = #{username}
    and users.password = #{password}
    and users.head_img = #{headImg}
    and users.phone like concat('%',#{phone},'%')
    and users.address = #{address}
    and users.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from users users

    and users.id = #{id}
    and users.name like concat('%',#{name},'%')
    and users.sex = #{sex}
    and users.age = #{age}
    and users.username = #{username}
    and users.password = #{password}
    and users.head_img = #{headImg}
    and users.phone like concat('%',#{phone},'%')
    and users.address = #{address}
    and users.create_time = #{createTime}
